//! The words of uses.ink's diagnostics and notices, from `diag/catalog.toml`, and how they read
//! in a terminal.
//!
//! [`Message`] and [`Fix`] are the catalog's templates filled with a problem's or a notice's
//! fields; their `Display` arms are generated by `cargo xtask diag` into `generated.rs`.
//! [`Terminal`] lays a [`Diagnostic`] or a [`Notice`] out as plain text.

use std::fmt;

use model::{Announcement, ContentPath, Diagnostic, Notice, Problem};

mod catalog;
mod evidence;
#[allow(clippy::too_many_lines, clippy::match_same_arms, reason = "generated: one match arm per catalog entry")]
mod generated;
mod plain;
mod terminal;

pub use catalog::{Catalog, Unreadable, Wording};
pub use evidence::{Because, Pin, Short, Value};
pub use plain::Plain;
pub use terminal::Terminal;

/// What a message or fix is about.
#[derive(Clone, Copy, Debug)]
enum Said<'a> {
    Problem(&'a Problem),
    Announcement(&'a Announcement),
}

/// The catalog's message for a problem or a notice.
#[derive(Clone, Copy, Debug)]
pub struct Message<'a>(Said<'a>);

impl<'a> From<&'a Problem> for Message<'a> {
    fn from(problem: &'a Problem) -> Self {
        Self(Said::Problem(problem))
    }
}

impl<'a> From<&'a Announcement> for Message<'a> {
    fn from(announcement: &'a Announcement) -> Self {
        Self(Said::Announcement(announcement))
    }
}

impl fmt::Display for Message<'_> {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.0 {
            Said::Problem(problem) => Self::problem(problem, out),
            Said::Announcement(announcement) => Self::announcement(announcement, out),
        }
    }
}

/// The catalog's fix for a problem or a notice, when it has one.
#[derive(Clone, Copy, Debug)]
pub struct Fix<'a>(Said<'a>);

impl<'a> Fix<'a> {
    /// The fix for `problem`, when the catalog gives one.
    pub fn of_problem(problem: &'a Problem) -> Option<Self> {
        Self::problem_has(problem).then_some(Self(Said::Problem(problem)))
    }

    /// The fix for `announcement`, when the catalog gives one.
    pub fn of_announcement(announcement: &'a Announcement) -> Option<Self> {
        Self::announcement_has(announcement).then_some(Self(Said::Announcement(announcement)))
    }
}

impl fmt::Display for Fix<'_> {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.0 {
            Said::Problem(problem) => Self::problem(problem, out),
            Said::Announcement(announcement) => Self::announcement(announcement, out),
        }
    }
}

/// A list of paths in prose: `a`, `a and b`, `a, b and c`, or `no files`.
#[derive(Clone, Copy, Debug)]
pub struct Paths<'a>(pub &'a [ContentPath]);

impl fmt::Display for Paths<'_> {
    fn fmt(&self, out: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.0.is_empty() {
            return out.write_str("no files");
        }
        for (i, path) in self.0.iter().enumerate() {
            let sep = match i {
                0 => "",
                i if i + 1 == self.0.len() => " and ",
                _ => ", ",
            };
            write!(out, "{sep}{path}")?;
        }
        Ok(())
    }
}

impl<'a> From<&'a Diagnostic> for Message<'a> {
    fn from(diagnostic: &'a Diagnostic) -> Self {
        Self::from(&diagnostic.problem)
    }
}

impl<'a> From<&'a Notice> for Message<'a> {
    fn from(notice: &'a Notice) -> Self {
        Self::from(&notice.announcement)
    }
}
